function audioTip(english: string): string {
  if (/\bthirteen\b/.test(english)) return 'Contrast thirTEEN with THIRty. Listen for the stress and repeat the page number before continuing.';
  if (/\breceipt\b/.test(english)) return 'Say receipt with a silent p: stress the second syllable. Keep please gentle and clear.';
  if (/\bcupboard\b/.test(english)) return 'In cupboard, the p is silent. Say the word as two syllables, with stress on the first.';
  if (/^(Could|Would|Can|May|Shall)\b/.test(english)) return 'Say the opening request smoothly. Stress the action and the item, time or place; use a friendly tone.';
  if (/^(What|Where|When|Who|Which|How)\b/.test(english)) return 'Stress the question word and the detail you want to know. Pause after the question and listen to the answer.';
  if (/\b(turn|Turn|Go|Walk|Cross|First|Then)\b/.test(english)) return 'Give one instruction at a time. Stress the action and landmark; pause between steps so the listener can follow.';
  if (/\b(rupees|hundred|thousand|thirty|half past|at nine|at ten)\b/.test(english)) return 'Say the amount or time slowly first, then in the full sentence. Ask your partner to repeat it to check understanding.';
  if (/\b(hurts|works|lives|studies|teaches|washes|makes|starts)\b/.test(english)) return 'Keep the ending of the verb audible. Listen to the model, repeat the verb, then say the whole sentence naturally.';
  return 'Stress the main information in the sentence. Pause at the punctuation, then repeat with your own details and check that your partner understood.';
}

export function enhanceEverydayLesson(lesson: Lesson): Lesson {
  if (lesson.number < 101 || lesson.number > 200) return lesson;
  const [pattern, explanation, incorrect, correct, practice, vocabulary] = teaching[lesson.number - 101];
  const model = models[lesson.number];
  const titleEnglish = model?.[0] ?? lesson.titleEnglish;
  const titleSinhala = model?.[1] ?? lesson.titleSinhala;
  const sourcePhrases = model
    ? model.slice(2).map((pair, index) => {
      const [english, sinhala] = pair.split('|');
      return { ...lesson.phrases[index], english, sinhala };
    })
    : lesson.phrases;
  const phrases = sourcePhrases.map((phrase, index) => {
    const revision = phraseRevisions[lesson.number]?.[index];
    if (!revision) return phrase;
    const [english, sinhala] = revision.split('|');
    return { ...phrase, english, sinhala };
  });
  const keyVocabulary = vocabulary.split('|').map(pair => {
    const [english, sinhala] = pair.split('=');
    return { english, sinhala };
  });
  return {
    ...lesson, titleEnglish, titleSinhala,
    summarySinhala: `${titleSinhala}. ${practice}`,
    grammarRule: {
      ruleTitleSinhala: titleSinhala,
      explanationSinhala: explanation,
      sinhalaVsEnglishPattern: {
        sinhalaOrder: 'සිංහල අර්ථය බලා, පහත ඉංග්‍රීසි රටාවේ වචන අනුපිළිවෙළ පුහුණු කරන්න.',
        englishOrder: pattern,
        exampleSinhala: phrases[0].sinhala,
        exampleEnglish: phrases[0].english,
      },
    },
    phrases: phrases.map(phrase => ({
      ...phrase,
      teacherAudioTip: audioTip(phrase.english),
      notesSinhala: `${explanation} මෙම වාක්‍යයේ අර්ථය තහවුරු කර, ඔබේම තොරතුරු යොදා වෙනස් කර කියන්න.`,
    })),
    keyVocabulary,
    guidedPracticeSinhala: practice,
    commonMistake: {
      incorrect, correct,
      explanationSinhala: `“${incorrect}” වෙනුවට “${correct}” කියන්න. ${explanation}`,
      contextExample: correct,
    },
    teacherVoiceAdviceSinhala: `${titleSinhala}: ${explanation} මුලින් අසා, ඊළඟට අර්ථවත් කොටස්වලට කියන්න. ${practice}`,
  };
}
